// The island's node:events MODULE-LEVEL statics, differentially against
// Node. `on` and `once` have always been announced as named exports of
// node:events by the island's builtin table, but `on` — the async
// iterator over an emitter's events — had no backing property, so
// `import { on } from "events"` bound undefined and only failed at the
// call. These scenarios pin both names and the three exits Node's `on`
// documents: a consumer `break`, an `options.close` event, and an
// 'error' event arriving behind buffered ones.
import { EventEmitter, on, once } from "node:events";

export async function report() {
  const lines = [];
  const push = (label, v) => lines.push(label + " " + v);

  push("types:", typeof on + "|" + typeof once);

  // Buffered events drain before the consumer's break ends iteration.
  const buffered = new EventEmitter();
  const ticks = on(buffered, "tick");
  buffered.emit("tick", 1, "a");
  buffered.emit("tick", 2, "b");
  buffered.emit("tick", 3, "c");
  const seen = [];
  for await (const args of ticks) {
    seen.push(args.join("/"));
    if (args[0] === 2) break;
  }
  push("break:", seen.join(","));

  // options.close names the events that end the iterator; anything
  // already queued still comes out first.
  const closing = new EventEmitter();
  const chunks = on(closing, "data", { close: ["end"] });
  closing.emit("data", "x");
  closing.emit("data", "y");
  closing.emit("end");
  const body = [];
  for await (const args of chunks) body.push(args[0]);
  push("close:", body.join("") + "|" + body.length);

  // 'error' behind a buffered event: the buffered one yields, then the
  // iterator throws with the emitted error.
  const failing = new EventEmitter();
  const items = on(failing, "item");
  failing.emit("item", "kept");
  failing.emit("error", new Error("boom"));
  const before = [];
  let caught = "none";
  try {
    for await (const args of items) before.push(args[0]);
  } catch (e) {
    caught = e.message;
  }
  push("error:", before.join(",") + "|" + caught);

  // The sibling static that already worked, for contrast: once resolves
  // with the emitted argument list.
  const settling = new EventEmitter();
  const pending = once(settling, "ready");
  settling.emit("ready", 7, 8);
  push("once:", (await pending).join(","));

  // The iterator is its own asyncIterator, as Node's is.
  const selfish = new EventEmitter();
  const iterator = on(selfish, "n");
  push("self:", (iterator[Symbol.asyncIterator]() === iterator) + "|" + typeof iterator.next);
  iterator.return();

  return lines.join("\n");
}
